/*
 * Tenor narrative: plain-English (Simple view) and finance-language (Investor view) text built from templates.
 * Every number comes from the model. Nothing here is generated by an AI model.
 * Works in the browser (window.TenorNarrative) and in Node (module.exports).
 */
(function (root) {
  'use strict';

  const isNum = (x) => typeof x === 'number' && isFinite(x);

  function money(x, cur, opts = {}) {
    if (!isNum(x)) return 'n/a';
    const sign = x < 0 ? '-' : '';
    const a = Math.abs(x);
    let s;
    if (opts.compact !== false && a >= 1e9) s = (a / 1e9).toFixed(a >= 1e10 ? 1 : 2) + 'bn';
    else if (opts.compact !== false && a >= 1e6) s = (a / 1e6).toFixed(a >= 1e7 ? 1 : 2) + 'm';
    else s = Math.round(a).toLocaleString('en-GB');
    return (cur ? cur + ' ' : '') + (sign ? '\u2212' : '') + s;
  }
  const pct = (x, d = 1) => (isNum(x) ? (x * 100).toFixed(d) + '%' : 'n/a');
  const ratio = (x) => (isNum(x) ? x.toFixed(2) + 'x' : 'n/a');
  const years = (x) => (isNum(x) ? x.toFixed(1) + ' years' : 'n/a');
  const yearOf = (m, t) => (isNum(t) ? m.years[t - 1] : null);

  const MITIGATIONS = {
    price_10: 'Agree prices in advance with buyers (offtake contracts), or plan for a cheaper cost base.',
    price_20: 'Secure forward sales or a price floor, and keep a cash reserve for a bad year.',
    volume_20: 'Test demand early, sign supply or sales agreements, and phase the build so capacity follows demand.',
    opex_15: 'Fix key costs with suppliers, budget a contingency, and track costs monthly against plan.',
    delay_1: 'Ask lenders for a grace period that covers a late start, and lock in permits and equipment orders early.',
    fx: 'Borrow in the currency you earn in where possible, or hedge, and keep a reserve in the loan currency.',
  };

  /* "What this means" panel and executive summary */
  function summary(ctx, audience = 'simple') {
    const { input, model: m, sens } = ctx;
    const k = m.kpis, cur = input.currency;
    const target = (input.defaults && input.defaults.dscr_target) || 1.3;
    const hasLoan = m.loans.length > 0;
    const top = sens && sens.ranked && sens.results.find((r) => r.id === sens.ranked[0]);
    const dscrYear = hasLoan && isNum(k.dscrMin) ? yearOf(m, m.out.dscr.findIndex((x) => x !== null && Math.abs(x - k.dscrMin) < 1e-12)) : null;
    const lowCashYear = yearOf(m, m.out.cash.findIndex((x, t) => t > 0 && x === k.lowestCash));
    const out = { headline: '', paragraphs: [], tone: 'ok' };

    if (audience === 'investor') {
      if (hasLoan) {
        out.headline = isNum(k.dscrMin) && k.dscrMin >= target ? 'Debt service is covered with headroom.' : isNum(k.dscrMin) && k.dscrMin >= 1 ? 'Debt service is covered, below the target ratio.' : 'Debt service is not covered in every year.';
        out.tone = isNum(k.dscrMin) && k.dscrMin >= target ? 'ok' : isNum(k.dscrMin) && k.dscrMin >= 1 ? 'watch' : 'risk';
        out.paragraphs.push('Minimum DSCR ' + ratio(k.dscrMin) + (dscrYear ? ' (' + dscrYear + ')' : '') + ' against a ' + ratio(target) + ' target; average ' + ratio(k.dscrAvg) + '; LLCR ' + ratio(k.llcr) + '. Gearing ' + pct(k.gearing) + '.');
      } else {
        out.headline = k.lowestCash >= 0 ? 'Fully equity or grant funded, with no cash shortfall.' : 'Equity-funded with a cash shortfall to close.';
        out.tone = k.lowestCash >= 0 ? 'ok' : 'risk';
        out.paragraphs.push('No debt in the plan. Lowest cash balance ' + money(k.lowestCash, cur) + (lowCashYear ? ' (' + lowCashYear + ')' : '') + (isNum(k.runwayMonths) ? '; runway ' + k.runwayMonths.toFixed(0) + ' months.' : '.'));
      }
      out.paragraphs.push('Project IRR ' + pct(k.projectIRR) + ', equity IRR ' + pct(k.equityIRR) + ', NPV at ' + pct(k.discountRate, 0) + ' of ' + money(k.npv, cur) + ', payback ' + years(k.paybackYears) + '. EBITDA margin ' + pct(k.ebitdaMargin) + ' in the representative year.');
      if (top) out.paragraphs.push('Most sensitive to: ' + top.label.toLowerCase() + ' (NPV change ' + money(top.delta.npv, cur) + (isNum(top.result.dscrMin) ? ', minimum DSCR ' + ratio(top.result.dscrMin) : '') + ').');
      return out;
    }

    // Simple view
    if (hasLoan) {
      if (isNum(k.dscrMin) && k.dscrMin >= target) {
        out.headline = 'Your plan has room to work.';
        out.paragraphs.push('At your current estimates, the money the project makes covers its running costs and loan payments every year, with some to spare. In the tightest year, cash covers the loan payment ' + k.dscrMin.toFixed(1) + ' times. Lenders usually look for at least ' + target.toFixed(1) + '.');
      } else if (isNum(k.dscrMin) && k.dscrMin >= 1) {
        out.headline = 'It works, but it is tight.';
        out.tone = 'watch';
        out.paragraphs.push('The project can pay its loan, but in ' + (dscrYear || 'its tightest year') + ' cash only covers the payment ' + k.dscrMin.toFixed(2) + ' times. Most lenders want at least ' + target.toFixed(1) + ', so they may ask for a longer repayment period, a grace period or more of your own money.');
      } else {
        out.headline = 'As planned, the loan payments are too heavy.';
        out.tone = 'risk';
        out.paragraphs.push('In ' + (dscrYear || 'at least one year') + ' the project does not make enough cash to cover its loan payment. Try a longer repayment period, a grace period, a smaller loan, or check your sales and cost estimates.');
      }
    } else if (k.lowestCash >= 0) {
      out.headline = 'Your cash does not run out.';
      out.paragraphs.push('With your own money' + (m.out.grantIn.some((x) => x > 0) ? ' and the grant' : '') + ', the project never runs short of cash at these estimates.');
    } else {
      out.headline = 'You will need more money to get through the early years.';
      out.tone = 'risk';
      out.paragraphs.push('Cash falls to ' + money(k.lowestCash, cur) + (lowCashYear ? ' in ' + lowCashYear : '') + '. You would need about ' + money(k.peakFunding, cur) + ' more' + (isNum(k.runwayMonths) ? ', or cash runs out after about ' + k.runwayMonths.toFixed(0) + ' months' : '') + '.');
    }
    if (isNum(k.paybackYears)) out.paragraphs.push('The money put in comes back in about ' + k.paybackYears.toFixed(1) + ' years.');
    else if (m.out.projectFCF.slice(1).some((x) => x < 0)) out.paragraphs.push('Within the ' + m.N + ' years modelled, the cash coming in does not fully pay back what goes in.');
    if (top) out.paragraphs.push('The estimate that matters most: ' + top.simple.toLowerCase() + ' would change the value of the project by ' + money(top.delta.npv, cur) + '.');
    return out;
  }

  /* "Explain this number" text for headline figures */
  function explain(key, ctx) {
    const { input, model: m } = ctx; const k = m.kpis; const cur = input.currency; const st = k.steadyYear;
    const E = {
      sales: { title: 'Expected yearly sales', formula: 'Sales = ' + ((ctx.sector && ctx.sector.revenue_explained) || 'volume times price'), value: money(m.out.revenue[st], cur, { compact: false }) + ' in ' + m.years[st - 1] + ', after ramp-up.' },
      costs: { title: 'Yearly running costs', formula: 'Running costs = variable costs (which rise with what you sell) + fixed costs (which you pay anyway).', value: money(m.out.varCost[st], cur) + ' variable plus ' + money(m.out.fixCost[st], cur) + ' fixed in ' + m.years[st - 1] + '.' },
      debt: { title: 'Largest yearly loan payment', formula: 'Loan payment = interest on what is still owed + the part of the loan repaid that year.', value: money(k.largestDebtService, cur, { compact: false }) + (k.largestDebtServiceYear ? ' in ' + m.years[k.largestDebtServiceYear - 1] : '') + '.' },
      payoff: { title: 'Loan paid off by', formula: 'Final year = first drawdown year + years to repay - 1.', value: k.loanPaidOffYear ? String(m.years[k.loanPaidOffYear - 1]) : 'No loan.' },
      dscr: { title: 'DSCR', formula: 'DSCR = cash available for debt service / loan payment that year. Cash available = sales - running costs - tax - extra cash tied up in stock and unpaid bills.', value: 'Lowest ' + ratio(k.dscrMin) + ', average ' + ratio(k.dscrAvg) + '.' },
      irr: { title: 'Project IRR', formula: 'The yearly return that makes the value today of all the project\'s cash (money out to build it, money in from running it) add up to zero.', value: pct(k.projectIRR) + ' a year.' },
      npv: { title: 'NPV', formula: 'NPV = each year\'s free cash divided by (1 + ' + pct(k.discountRate, 0) + ') for every year you wait for it, added up.', value: money(k.npv, cur, { compact: false }) + '.' },
      payback: { title: 'Payback', formula: 'Years until the running total of free cash turns positive.', value: years(k.paybackYears) + '.' },
    };
    return E[key] || null;
  }

  function mitigation(id) { return MITIGATIONS[id] || 'Plan a buffer and agree terms early.'; }

  const api = { money, pct, ratio, years, summary, explain, mitigation, MITIGATIONS };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.TenorNarrative = api;
})(typeof self !== 'undefined' ? self : this);
